| BLACKPYRAMIDS_303's ColdFire runtime as one unit. GENERATED by tools/ot303/octabam_module.py
| from tools/ot303/cf/{machine.s,control.c,record.c,params.c} and the Y table -- do not edit;
| edit those and regenerate. Subsections keep the standalone link's layout: 0 .text, 1 .rodata,
| 2 .rodata.*, 3 .data (tools/build_blackpyramids_303.py runtime.ld).
        .text 0
| ---- machine.s
| SPDX-License-Identifier: MIT
| SPDX-FileCopyrightText: 2026 Zac Kyoti; ported from octabam modules/analog-bassdrum/machine.s
| (repeat98, MIT), which measured these seams (and Machinedrum's before it).
|
| OT-303 registration: machine row 5 in the track's machine chooser and in SRC SETUP, stored as FLEX
| plus the signature 'O','T',1 in unused NEIGHBOR page bytes (part + 0x2a + 18 + 30 t), on any track,
| one per DSP core. An assignment seeds both Part copies with the OT-303's knobs from when the track
| last left it, or the defaults (FLEX's values stashed beside the signature, put back when the track
| leaves OT-303, its knobs parked in their place); reselecting keeps the patch. Each stub is reached by a detour (tools/build_blackpyramids_303.py) and replays the stock
| instructions it displaced. ANALOG BD's engine browser is not ported (no detours on the pool).
        .text
        .global ot_machine_name, ot_src_names, ot_main_commit, ot_src_commit, ot_src_commit2
        .global ot_name_a, ot_name_b, ot_setup_row, ot_chooser_row, ot_setup_open, ot_chooser_open
        .global ot_setup_edit6, ot_setup_draw6, ot_resolve_pb, ot_validate, ot_stock_validate
        .global ot_tick_hook, ot_glyph, ot_step_hook, ot_note_hook, ot_chooser_level, ot_setup_value_hook
        .global ot_slic_a, ot_slic_b, ot_slic_c, ot_pmtr_pb
        .global ot_live_req_hook, ot_live_midi_hook, ot_live_chrom_hook, ot_live_rel_hook, ot_oneshot_hook
        .global ot_rec_chrom_hook, ot_rec_midi_hook, ot_idle_hook
        .global ot_plock_hook
        .global ot_led_hook, ot_slices_hook, ot_slots_hook, ot_oct_hook, ot_chrom_key_hook, ot_chrom_limit_hook, ot_chrom_img_hook, ot_page_key_hook

        .equ    OT_ROW, 5
        .equ    FLEX, 1
        .equ    SRC_CURSOR, 0x460d5c30
        .equ    BANK_PTR, 0x46c82456
        .equ    PART_OFF, 0x8ed80
        .equ    SRAM_PART, 0x100a4ece
        .equ    SIG_OFF, 0x2a + 18
        .equ    PAGE2_GAP, 0x1da - 0x2a
        .equ    PB_TABLE, 0x400d5f38

| a0 = the Part, d0 = the track, d1 = 1 sign / 0 clear: control.c ot_assign (FLEX's values stashed
| while the track is an OT-303, put back when it leaves; both Part copies). Keeps every register.
ot_sig_write:
        lea	-16(%sp),%sp
        movem.l	%d0-%d1/%a0-%a1,(%sp)
        move.l	%d1,-(%sp)
        move.l	%d0,-(%sp)
        move.l	%a0,-(%sp)
        jsr	ot_assign.l
        lea	12(%sp),%sp
        movem.l	(%sp),%d0-%d1/%a0-%a1
        lea	16(%sp),%sp
        rts

| the chooser's row name: row 5 is ours, the rest stock (0x400334d8 displaced: move.l d2,-(sp);
| move.l 8(sp),d1)
ot_machine_name:
        move.l	4(%sp),%d0
        cmpi.l	#OT_ROW,%d0
        beq.s	1f
        move.l	%d2,-(%sp)
        move.l	8(%sp),%d1
        jmp	(0x400334de).l
1:      lea	ot_name(%pc),%a0
        move.l	%a0,%d0
        rts

| SRC SETUP's six machine names (the stock five, then ours): the operand of `lea abs.l,a5`
        .balign 4
ot_src_names:
        .long   0x400b3eac
        .long   0x400b3e98
        .long   0x400b7c67
        .long   0x400b5413
        .long   0x400b7a63
        .long   ot_name

ot_admit:
        lea	-20(%sp),%sp
        movem.l	%d1/%a0-%a1,8(%sp)
        move.l	%a0,(%sp)
        move.l	%d0,4(%sp)
        jsr	ot_admit_track.l
        movem.l	8(%sp),%d1/%a0-%a1
        lea	20(%sp),%sp
        rts

| the main chooser's commit (0x4007981c: its three displaced words replayed below)
ot_main_commit:
        lea	-12(%sp),%sp
        movem.l	%d0-%d1/%a0,(%sp)
        movea.l	%a1,%a0
        adda.l	%d0,%a0
        adda.l	#PART_OFF,%a0
        move.l	%d1,%d0
        cmpi.l	#OT_ROW,%d4
        bne.s	.mc_other
        bsr	ot_admit
        tst.l	%d0
        beq.s	.mc_refuse
        move.l	%d1,%d0
        moveq	#1,%d1
        bsr	ot_sig_write
        moveq	#FLEX,%d4
        bra.s	.mc_store
.mc_other:
        moveq	#0,%d1
        bsr	ot_sig_write
.mc_store:
        movem.l	(%sp),%d0-%d1/%a0
        lea	12(%sp),%sp
        .word   0x7710,0x1084,0xd081
        jmp	(0x40079822).l
.mc_refuse:
        movem.l	(%sp),%d0-%d1/%a0
        lea	12(%sp),%sp
        pea	0x30.w
        pea	ot_reject_name(%pc)
        jsr	(0x4005a2b8).l
        addq.l	#8,%sp
        jmp	(0x4007989c).l

| SRC SETUP's two commit paths
ot_src_commit:
        pea	(0x4005a61c).l
        bra.s	ot_src_common
ot_src_commit2:
        pea	(0x4005a856).l
ot_src_common:
        move.l	(SRC_CURSOR).l,%d1
        lea	-12(%sp),%sp
        movem.l	%d0/%d2/%a0,(%sp)
        movea.l	%a1,%a0
        adda.l	%d0,%a0
        adda.l	#PART_OFF,%a0
        move.l	%d2,%d0
        cmpi.l	#OT_ROW,%d1
        bne.s	.sc_other
        bsr	ot_admit
        tst.l	%d0
        beq.s	.sc_refuse
        move.l	%d2,%d0
        moveq	#1,%d1
        bsr	ot_sig_write
        moveq	#FLEX,%d1
        bra.s	.sc_go
.sc_other:
        move.l	%d1,-(%sp)
        moveq	#0,%d1
        bsr	ot_sig_write
        move.l	(%sp)+,%d1
.sc_go:
        movem.l	(%sp),%d0/%d2/%a0
        lea	12(%sp),%sp
        rts
.sc_refuse:
        movem.l	(%sp),%d0/%d2/%a0
        lea	12(%sp),%sp
        moveq	#0,%d1
        move.b	(%a0),%d1
        move.l	%d1,(SRC_CURSOR).l
        pea	0x30.w
        pea	ot_reject_name(%pc)
        jsr	(0x4005a2b8).l
        addq.l	#8,%sp
        rts

ot_setup_open:
        move.b	(%a0),%d3
        move.l	%d0,-(%sp)
        mvs.b	%d3,%d0
        bsr	ot_row_type
        move.l	%d0,%d3
        move.l	(%sp)+,%d0
        mvs.b	%d3,%d4
        pea	(0x400bb704).l
        jmp	(0x400585e6).l

| SETUP's editor and drawer use the track's FLEX slot for row 5 (d2/d6 = the row; replays d * 6); the editor
| takes NEIGHBOR's on a track that is not an OT-303 (the parked knobs, MT35)
ot_setup_edit6:
        cmpi.l	#FLEX,%d2 | FLEX's row on an OT-303 track shows FLEX's stash: not editable
        bne.s	2f | here (its bytes are the OT-303's SETUP knobs)
        lea	-16(%sp),%sp
        movem.l	%d0-%d1/%a0-%a1,(%sp)
        move.l	%d4,-(%sp)
        jsr	ot_track_is.l
        addq.l	#4,%sp
        tst.l	%d0
        movem.l	(%sp),%d0-%d1/%a0-%a1
        lea	16(%sp),%sp
        beq.s	2f
        jmp	(0x4003a624).l
2:      cmpi.l	#OT_ROW,%d2 | the OT-303 row: FLEX's bytes on an OT-303 track, the parked
        bne.s	1f | knobs (NEIGHBOR's SETUP bytes) on another (control.c)
        lea	-12(%sp),%sp
        movem.l	%d1/%a0-%a1,(%sp)
        move.l	%d4,-(%sp)
        jsr	ot_setup_edit_row.l
        addq.l	#4,%sp
        move.l	%d0,%d2
        movem.l	(%sp),%d1/%a0-%a1
        lea	12(%sp),%sp
1:      move.l	%d2,%d0
        lsl.l	#3,%d0
        add.l	%d2,%d2
        sub.l	%d2,%d0
        jmp	(0x4003a536).l
ot_setup_draw6:
        clr.l	(ot_preview_flex).l
        clr.l	(ot_preview_ot).l
        cmpi.l	#FLEX,%d6
        bne.s	2f
        moveq	#1,%d7
        move.l	%d7,(ot_preview_flex).l
2:      cmpi.l	#OT_ROW,%d6
        bne.s	1f
        moveq	#1,%d7
        move.l	%d7,(ot_preview_ot).l
        moveq	#FLEX,%d6
1:      move.l	%d6,%d7
        lsl.l	#3,%d7
        add.l	%d6,%d6
        sub.l	%d6,%d7
        jmp	(0x4003cda0).l

ot_chooser_open:
        mvs.b	(%a0),%d0
        bsr	ot_row_type
        move.l	%d0,-(%sp)
        pea	(0x460e7386).l
        jmp	(0x40078890).l

| the machine window's focus (0x400788c4, a0 = the track's type byte): stock opens STATIC and FLEX
| (type < 2) on the sample list, any other machine on the machine list. An OT-303 (stored as FLEX)
| reads as its row (5): a track double-tap shows the machine list, as for THRU / NEIGHBOR / PICKUP.
ot_chooser_level:
        mvz.b	(%a0),%d0
        bsr	ot_row_type
        moveq	#1,%d2
        cmp.l	%d0,%d2
        jmp	(0x400788ca).l

ot_name_a:
        bsr.s	ot_name_pick
        jmp	(0x4003d722).l
ot_name_b:
        bsr.s	ot_name_pick
        jmp	(0x4004c374).l
ot_name_pick:
        bsr	ot_row_type
        lea	ot_src_names(%pc),%a0
        move.l	(%a0,%d0.l*4),%d1
        rts

ot_setup_row:
        mvs.b	(%a0),%d0
        lea	24(%sp),%sp
        bsr.s	ot_row_type
        jmp	(0x4003c986).l
ot_chooser_row:
        mvs.b	(%a0),%d0
        bsr.s	ot_row_type
        cmp.l	%d0,%d2
        bne.s	1f
        jmp	(0x400786ce).l
1:      jmp	(0x400786fc).l
| d0 = the stored type, a0 -> it in the Part: 5 for an OT-303 track
ot_row_type:
        lea	-20(%sp),%sp
        movem.l	%d1/%a0-%a1,8(%sp)
        move.l	%d0,(%sp)
        move.l	%a0,4(%sp)
        jsr	ot_type.l
        movem.l	8(%sp),%d1/%a0-%a1
        lea	20(%sp),%sp
        rts

ot_resolve_pb:
        mvs.b	%d5,%d0
        bsr	ot_row_type
        cmpi.l	#OT_ROW,%d0
        bne.s	1f
        move.l	%a0,-(%sp)
        jsr	ot_track_page.l
        addq.l	#4,%sp
        jmp	(0x40031ed6).l
1:      lea	(PB_TABLE).l,%a0
        jmp	(0x40031ece).l

| MT13: the LFO page's PMTR formatter (0x4003bf64) names a machine destination from PB_TABLE by the
| track's stored type (a0 -> the Part type byte; d1 = the track): an OT-303 (stored as FLEX) reads row 5,
| our page, so it lists PTCH CUT RES ENV DEC ACC
ot_pmtr_pb:
        mvs.b	(%a0),%d0
        bsr	ot_row_type
        lea	(PB_TABLE).l,%a0
        jmp	(0x4003c054).l | a2 = PB_TABLE[d0]

| MT18, live notes (control.c ot_live_*). The stock voice request 0x40005030(track, cmd, flags, slot):
| its callers for a track key, a chromatic key, the trig preview and MIDI notes 36-43 mark the track's
| live note pending (ret, track, cmd to C). Replays the 8 displaced bytes.
ot_live_req_hook:
        move.l	8(%sp),-(%sp) | cmd
        move.l	8(%sp),-(%sp) | track
        move.l	8(%sp),-(%sp) | the return address
        jsr	ot_live_req.l
        lea	12(%sp),%sp
        lea	-24(%sp),%sp
        movem.l	%d2-%d6/%a2,(%sp)
        jmp	(0x40005038).l

| a MIDI chromatic note (0x4000e746: d2 = the track, (a3) = the note, 1(a3) its velocity, a5 = the mailboxes, d4 -> the
| staged PTCH lock, a2 -> the held note): post the START; on an OT-303 track skip FLEX's PTCH lock
| (control.c keeps the note as a pitch offset)
ot_live_midi_hook:
        moveq	#29,%d1
        move.l	%d1,(%a5,%d2.l*4)
        mvz.b	1(%a3),%d0 | MT27: the velocity (the message is status, note, velocity)
        move.l	%d0,-(%sp)
        mvz.b	(%a3),%d0
        move.l	%d0,-(%sp)
        move.l	%d2,-(%sp)
        jsr	ot_live_midi.l
        lea	12(%sp),%sp
        tst.l	%d0
        beq.s	1f
        jmp	(0x4000e75a).l
1:      jmp	(0x4000e74c).l

| a chromatic trig key (0x4004fc84: d2 = the track, a2 = 5 idx + 4, FLEX's PTCH value): on an OT-303
| track the staged PTCH lock is not written (control.c keeps idx - 12 as a pitch offset)
ot_live_chrom_hook:
        move.l	16(%sp),-(%sp) | the chromatic handler's caller (MT23)
        move.l	%a2,-(%sp)
        move.l	%d2,-(%sp)
        jsr	ot_live_chrom.l
        lea	12(%sp),%sp
        tst.l	%d0
        bne.s	1f
        move.l	%d2,%d0
        lsl.l	#5,%d0
        lea	(0x46c7dfda).l,%a0
        move.w	%a2,%d1
        move.b	%d1,(%a0,%d0.l)
1:      jmp	(0x4004fc94).l

| the frame builder's release (0x4000b4f6: the track's mailbox has bit 6; 114(sp) = the track, a1
| live): control.c ot_live_release. Replays the 10 displaced bytes.
ot_live_rel_hook:
        move.l	%a1,-(%sp)
        move.l	118(%sp),-(%sp)
        jsr	ot_live_release.l
        addq.l	#4,%sp
        move.l	(%sp)+,%a1
        move.b	(0x80001828).l,%d4
        move.b	%d4,118(%sp)
        jmp	(0x4000b500).l

| a one-shot trig the step handler schedules (0x4009d4a8: d7 = the track, a0/a1 live): control.c
| ot_oneshot queues its note when armed. Replays the 6 displaced bytes.
ot_oneshot_hook:
        lea	-8(%sp),%sp
        movem.l	%a0-%a1,(%sp)
        move.l	%d7,-(%sp)
        jsr	ot_oneshot.l
        addq.l	#4,%sp
        movem.l	(%sp),%a0-%a1
        lea	8(%sp),%sp
        moveq	#61,%d2
        move.l	%d2,(%a0,%d7.l*4)
        jmp	(0x4009d4ae).l

| MT19: a chromatic key recorded live (0x4004fd0c: d2 = the track, a2 = FLEX's pitch value, d0 = the
| step): the PTCH lock in this machine's units (control.c ot_rec_pitch). Replays the 20 displaced
| bytes, the pushes and the call to 0x40042158; continues at its stack pop.
ot_rec_chrom_hook:
        move.l	%d0,-(%sp)
        move.l	20(%sp),-(%sp) | the chromatic handler's caller (MT23)
        move.l	%a2,-(%sp)
        move.l	%d2,-(%sp)
        jsr	ot_rec_chrom_pitch.l
        lea	12(%sp),%sp
        move.l	%d0,%a0
        move.l	(%sp)+,%d0
        move.l	(0x46c7e956).l,-(%sp)
        move.l	%d0,-(%sp)
        move.l	%a0,-(%sp)
        clr.l	-(%sp)
        move.l	%d2,-(%sp)
        jsr	(0x40042158).l
        jmp	(0x4004fd20).l

| MT19: a MIDI chromatic note recorded live (0x40062604: (a2 + 2) = the note, the track at
| 0x80000000): stock pushes FLEX's value 5 note - 356; this pushes ot_rec_pitch's. Replays the 14
| displaced bytes (d0, a0 are dead after them; d1 is kept).
ot_rec_midi_hook:
        move.l	%d1,-(%sp)
        mvs.b	2(%a2),%d0
        move.l	%d0,%d1
        lsl.l	#2,%d1
        add.l	%d1,%d0
        subi.l	#356,%d0
        move.l	%d0,-(%sp)
        mvz.b	(0x80000000).l,%d0
        move.l	%d0,-(%sp)
        jsr	ot_rec_pitch.l
        addq.l	#8,%sp
        move.l	(%sp)+,%d1
        move.l	%d0,-(%sp)
        jmp	(0x40062612).l

| MT22: the silent renderer 0x400047f0(track, ping, start, end), the packer's call for a track with no
| voice: an OT-303 track whose DSP core has not had the tables yet renders through ot_render instead
| (control.c ot_idle_feed). Replays the 6 displaced bytes.
ot_idle_hook:
        move.l	16(%sp),-(%sp) | end
        move.l	8(%sp),-(%sp) | track
        jsr	ot_idle_feed.l
        addq.l	#8,%sp
        tst.l	%d0
        beq.s	1f
        jmp	ot_render.l | the same arguments, the same return
1:      move.l	%d2,-(%sp)
        move.l	20(%sp),%d1
        jmp	(0x400047f6).l

| MT23, the trig-key modes (control.c). The trig LEDs (0x40044006: d1 the routine's argument): SLOTS /
| SLICES on an OT-303 track take stock's no-slot path 0x400441cc (all dark, the playhead while playing).
ot_led_hook:
        lea	-12(%sp),%sp
        movem.l	%d1/%a0-%a1,(%sp)
        jsr	ot_trigmode_dark.l
        tst.l	%d0
        movem.l	(%sp),%d1/%a0-%a1
        lea	12(%sp),%sp
        bne.s	1f
        move.l	(0x460d16f0).l,%d0
        jmp	(0x4004400c).l
1:      jmp	(0x400441cc).l

| SLICES' key handler 0x4004f8dc(track, idx, event): inert on an OT-303 track
ot_slices_hook:
        move.l	4(%sp),-(%sp)
        jsr	ot_track_is.l
        addq.l	#4,%sp
        tst.l	%d0
        beq.s	1f
        moveq	#0,%d0
        rts
1:      lea	-12(%sp),%sp
        movem.l	%d2-%d4,(%sp)
        jmp	(0x4004f8e4).l

| SLOTS' key handler 0x4004fa54(track, idx, event): inert on an OT-303 track
ot_slots_hook:
        move.l	4(%sp),-(%sp)
        jsr	ot_track_is.l
        addq.l	#4,%sp
        tst.l	%d0
        beq.s	1f
        moveq	#0,%d0
        rts
1:      move.l	%d3,-(%sp)
        move.l	%d2,-(%sp)
        move.l	12(%sp),%d2
        jmp	(0x4004fa5c).l

| CHROMATIC's octave (0x40045918, FUNC + LEFT / RIGHT; 8(sp) = the key): 0..3 on an OT-303 track
ot_oct_hook:
        move.l	8(%sp),-(%sp)
        jsr	ot_chrom_oct.l
        addq.l	#4,%sp
        moveq	#1,%d2
        jmp	(0x40045920).l

| a chromatic trig key (0x40050254, a0 = the key): another track never sees an OT-303 track's octave
ot_chrom_key_hook:
        lea	-12(%sp),%sp
        movem.l	%d1/%a0-%a1,(%sp)
        jsr	ot_chrom_sanitize.l
        movem.l	(%sp),%d1/%a0-%a1
        lea	12(%sp),%sp
        move.l	(0x460d16fc).l,%d0
        jmp	(0x4005025a).l

| the chromatic handler's range (0x4004fba8: d2 the track, a2 idx, d0 the event; 16(sp) its caller)
ot_chrom_limit_hook:
        lea	-16(%sp),%sp
        movem.l	%d0-%d1/%a0-%a1,(%sp)
        move.l	32(%sp),-(%sp)
        move.l	%d2,-(%sp)
        jsr	ot_chrom_limit.l
        addq.l	#8,%sp
        cmp.l	%a2,%d0
        movem.l	(%sp),%d0-%d1/%a0-%a1
        lea	16(%sp),%sp
        bcs.s	2f
        blt.s	2f
        moveq	#24,%d1
        jmp	(0x4004fbb4).l
2:      moveq	#24,%d1
        jmp	(0x4004fd68).l

| the CHROMATIC screen's keyboard image (0x40044968): the full one at every octave on an OT-303 track
ot_chrom_img_hook:
        lea	-12(%sp),%sp
        movem.l	%d0/%a0-%a1,(%sp)
        mvz.b	(0x100b14cc).l,%d0
        move.l	%d0,-(%sp)
        jsr	ot_track_is.l
        addq.l	#4,%sp
        tst.l	%d0
        movem.l	(%sp),%d0/%a0-%a1
        lea	12(%sp),%sp
        bne.s	1f
        moveq	#1,%d1
        cmp.l	(0x460d16fc).l,%d1
        bne.s	1f
        jmp	(0x40044972).l
1:      moveq	#1,%d1
        jmp	(0x40044988).l

ot_validate:
        jmp	ot_validate_part.l
ot_stock_validate:
        lea	-96(%sp),%sp
        movem.l	%d2-%d7/%a2-%fp,(%sp)
        jmp	(0x40002320).l

| publishes our page in the page table's row 5 (memory writes only: no UI or kernel call here)
ot_tick_hook:
        jsr	0x4005213c
        jsr	0x4007e940
        jsr	ot_ui_tick.l
        jmp	0x40052228

| the side columns' machine letter: the stock drawer (0x40040088, track d4, its type in a4) pushes the
| glyph from a table at fp - 24 indexed by type, or the M glyph (0x400bb3a6) for a MASTER T8; an
| OT-303 track gets a 3 (control.c ot_glyph3; the user's choice). Replays the 16 displaced bytes
| (0x4004012c: pea 1(a2); move.l d3,-(sp); pea 0x400bf10a; the glyph) and goes on at the draw call.
| d0/d1/a0/a1 are free here (the draw call clobbers them).
ot_glyph:
