        movem.l	%d0-%d1/%a0-%a1,(%sp)
        move.l	%a1,-(%sp)
        jsr	ot_setup_byte.l
        addq.l	#4,%sp
        move.b	%d0,3(%sp)
        movem.l	(%sp),%d0-%d1/%a0-%a1
        lea	16(%sp),%sp
        jmp	(0x4003b344).l
ot_slic_b:
        adda.l	#585563,%a0
        lea	-16(%sp),%sp
        movem.l	%d0-%d1/%a0-%a1,(%sp)
        move.l	%a0,-(%sp)
        jsr	ot_setup_byte.l
        addq.l	#4,%sp
        tst.b	%d0
        movem.l	(%sp),%d0-%d1/%a0-%a1
        lea	16(%sp),%sp
        jmp	(0x40044dc6).l
ot_slic_c:
        adda.l	#585563,%a0
        lea	-16(%sp),%sp
        movem.l	%d0-%d1/%a0-%a1,(%sp)
        move.l	%a0,-(%sp)
