        move.l	%d2,-(%sp)
        move.l	%d5,-(%sp)
        jsr	ot_plock_new.l
        lea	16(%sp),%sp
        move.l	%d0,4(%sp) | into the d1 slot
        movem.l	(%sp),%d0-%d1/%a0-%a1
        lea	16(%sp),%sp
        cmpi.l	#-1,%d0
        bne.s	1f | a lock: the handler path
        tst.l	%d1
        bmi.s	2f | stock's new lock
        move.b	%d1,(0x59,%a2,%a0.l)
